    ):
        self.model_manager = model_manager
        self.storage_dir = storage_dir
        self.chroma_store = chroma_store
        self.memories: Dict[str, MemoryNode] = {}
        self.hierarchy: Dict[str, List[str]] = defaultdict(list)
