        }

        save_path = os.path.join(self.storage_dir, 'hierarchical_memories.json')
        with open(save_path, 'w') as f:
            json.dump(data, f, indent=2)

    @log_and_time("Load Memories")
    def load_memories(self):
        """Load memories from disk"""
